// The address book.
//
// Contacts are records of type "contact" and nothing else, so this is the
// record browser with the type filled in plus the two things that are about
// people rather than about records: who has a birthday coming up, and a
// heading that says what this is.
//
// Everything else - the search, the card, adding, editing - is
// RecordBrowser's, shared with the collections tab, because a contact and a
// guitar pedal are the same shape and two copies of that view would have
// drifted apart the first time either was changed.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Chip from '@mui/joy/Chip';
import CakeIcon from '@mui/icons-material/CakeOutlined';

import RecordBrowser from './RecordBrowser';
import { ODb } from '../db';
import { BirthdayEvent, daysAwayText } from '../records';

// How far ahead the strip looks. Far enough to be worth glancing at, near
// enough that everything on it is actually soon.
const BIRTHDAY_DAYS = 45;

function Birthdays() {
    const [events, setEvents] = React.useState<BirthdayEvent[]>([]);

    React.useEffect(() => {
        const now = new Date();
        const to = new Date(now.getFullYear(), now.getMonth(), now.getDate() + BIRTHDAY_DAYS);
        ODb.birthdays(now, to)
            .then(b => setEvents(Array.isArray(b) ? b.slice(0, 8) : []))
            .catch(() => setEvents([]));
    }, []);

    if (events.length === 0) return null;

    const today = new Date();
    const midnight = new Date(today.getFullYear(), today.getMonth(), today.getDate());

    return (
        <Sheet
            variant="soft"
            sx={{
                borderRadius: 'sm', px: 1.5, py: 1, mb: 1.5,
                display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap',
            }}
        >
            <CakeIcon sx={{ fontSize: 18, color: 'text.tertiary' }} />
            {events.map((b, i) => {
                const when = new Date(b.Date + 'T00:00:00');
                const days = Math.round((when.getTime() - midnight.getTime()) / 86400000);
                return (
                    <Chip
                        key={b.Hash + i}
                        size="sm"
                        variant={days === 0 ? 'solid' : 'outlined'}
                        color={days <= 7 ? 'warning' : 'neutral'}
                        title={`${b.Name} — ${b.Date}${b.Age > 0 ? `, turns ${b.Age}` : ''}`}
                    >
                        {b.Name} · {daysAwayText(days)}
                    </Chip>
                );
            })}
        </Sheet>
    );
}

export default function Contacts() {
    // The page chrome already says "Contacts" above this, so there is no
    // heading here - two of them is the app saying it twice.
    return (
        <Box sx={{
            px: 2, pb: 1, display: 'flex', flexDirection: 'column',
            gap: 1.25, height: 'calc(100vh - 130px)', minHeight: 420,
        }}>
            <Birthdays />
            <RecordBrowser
                type="contact"
                noun="contact"
                emptyHint={
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', mt: 1 }}>
                        A contact is a heading with <code>:RECORD: contact</code> on it.
                        Add one here and the heading is written for you.
                    </Typography>
                }
            />
        </Box>
    );
}
