function baseName(path: string): string {
    const parts = path.split(/[\\/]/);
    return parts[parts.length - 1] || path;
}

// ---------------------------------------------------------------------------
// One cell being edited
// ---------------------------------------------------------------------------

// An ordinary property. `Allowed` is org's own `<PROPERTY>_ALL` mechanism, and
// where a file provides it this is a list to pick from rather than a box to type
// in - which is most of what makes filling in a column of estimates bearable.
// It stays a box as well, because the allowed values are a convenience org
// offers and never a constraint it enforces.
function PropertyEditor({ spec, cell, onDone }: {
    spec: ColumnSpec; cell: ColumnCell; onDone: (value: string | null) => void;
}) {
    const [value, setValue] = React.useState(editValue(cell));
    const allowed = spec.Allowed || [];

    // An editor may be finished in four ways - a value picked from the list,
    // Enter, Escape, or the focus moving away - and exactly one of them must be
    // the one that counts.
    //
    // Clicking an option in the list moves the focus first, so a blur that
    // committed straight away beat the click and put the *old* value back: the
    // list looked like it did nothing. Deferring the blur lets the click land,
    // and the latch is what stops the deferred blur then committing a second
    // time over the top of it.
    const finished = React.useRef(false);
    const finish = React.useCallback((v: string | null) => {
        if (finished.current) return;
        finished.current = true;
        onDone(v);
    }, [onDone]);

    const keys = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter') { e.preventDefault(); finish(value); }
        else if (e.key === 'Escape') { e.preventDefault(); finish(null); }
    };

    if (allowed.length > 0) {
        return (
            <Autocomplete
                autoFocus openOnFocus freeSolo size="sm"
                options={allowed}
                value={value}
                inputValue={value}
                onInputChange={(_, v) => setValue(v || '')}
                onChange={(_, v) => finish((v as string) ?? '')}
                onKeyDown={keys}
                onBlur={() => { const v = value; window.setTimeout(() => finish(v), 150); }}
                sx={{ minWidth: 110, '--Input-minHeight': '26px', fontSize: 12 }}
            />
        );
    }
    return (
        <Input
            autoFocus size="sm" value={value}
            onChange={e => setValue(e.target.value)}
            onKeyDown={keys}
            onBlur={() => finish(value)}
            sx={{ minWidth: 90, '--Input-minHeight': '26px', fontSize: 12 }}
        />
    );
}

// The keyword, offered from the heading's own file. Asked for when the menu
// opens rather than while three hundred rows are drawn, and asked per heading
// because a file may declare its own `#+TODO:` - offering a keyword the file
// does not have is offering to write something org will not read back.
function StatusEditor({ row, onPick }: { row: ColumnRow; onPick: (status: string) => void }) {
    const [states, setStates] = React.useState<string[] | null>(null);
    const asked = React.useRef(false);

    React.useEffect(() => { asked.current = false; setStates(null); }, [row.Hash]);

    const load = () => {
        if (asked.current) return;
        asked.current = true;
        ODb.validStatus(row.Hash)
            .then(r => setStates([...(r.Active || []), ...(r.Done || [])]))
            .catch(() => setStates([]));
    };

    const custom = getStatusCustomSx(row.Status);
    return (
        <Dropdown onOpenChange={(_, open) => { if (open) load(); }}>
            <MenuButton
                slots={{ root: Box }}
                slotProps={{ root: { sx: { cursor: 'pointer', display: 'inline-flex' } } }}
            >
                {row.Status ? (
                    <Chip
                        size="sm" variant="soft" color={getStatusColor(row.Status)}
                        startDecorator={getStatusIcon(row.Status)}
                        sx={{
                            '--Chip-minHeight': '20px', fontSize: 11, fontWeight: 'lg',
                            pointerEvents: 'none', '& .MuiSvgIcon-root': { fontSize: 12 },
                            ...(custom || {}),
                        }}
                    >{row.Status}</Chip>
                ) : (
                    <Chip
                        size="sm" variant="outlined" color="neutral"
                        sx={{
                            '--Chip-minHeight': '20px', fontSize: 11, borderStyle: 'dashed',
                            color: 'text.tertiary', pointerEvents: 'none', minWidth: 54,
                        }}
                    >none</Chip>
                )}
            </MenuButton>
            <Menu size="sm" placement="bottom-start">
                {states === null && <MenuItem disabled>loading…</MenuItem>}
                {states !== null && states.length === 0 && <MenuItem disabled>no keywords</MenuItem>}
                {(states || []).map(s => (
                    <MenuItem key={s} selected={s === row.Status} onClick={() => onPick(s)}>
                        {s}
                    </MenuItem>
                ))}
                {states !== null && states.length > 0 && (
                    <MenuItem onClick={() => onPick('')}>
                        <Typography level="body-xs" sx={{ fontStyle: 'italic' }}>no keyword</Typography>
                    </MenuItem>
                )}
            </Menu>
        </Dropdown>
    );
}

// ---------------------------------------------------------------------------
// The tab
// ---------------------------------------------------------------------------

type Editing = { hash: string; col: number } | null;

export default function Columns() {
    const nav = useNav();
    const [files, setFiles] = React.useState<string[]>([]);
    // Which file, kept in the browser settings: a column view is about one
    // project and a tab that forgets which is a tab you set up again each time.
    const [file, setFile] = useSetting('columnsFile');
    // The spec being used, and whether it is the file's own. Empty means "let
    // the server decide", which is how the file's own line and the configured
    // default get a chance to be the answer.
    const [spec, setSpec] = React.useState<string>('');
    const [specDraft, setSpecDraft] = React.useState<string>('');
    const [data, setData] = React.useState<ColumnsResult | null>(null);
    const [busy, setBusy] = React.useState(false);
    const [error, setError] = React.useState<string>('');
    const [folded, setFolded] = React.useState<Set<string>>(new Set());
    const [editing, setEditing] = React.useState<Editing>(null);
    const [sortOn, setSortOn] = React.useState<{ col: number; dir: 'asc' | 'desc' } | null>(null);
    const [saving, setSaving] = React.useState(false);

    React.useEffect(() => {
        ODb.getFiles().then(f => setFiles(f || [])).catch(() => setFiles([]));
    }, []);

    const load = React.useCallback((f: string, sp: string) => {
        if (!f) { setData(null); return; }
        setBusy(true);
        setError('');
        ODb.getColumns(f, sp || undefined)
            .then(r => {
                if (!r || !r.Ok) {
                    setError((r && r.Msg) || 'could not read that file');
                    setData(null);
                    return;
                }
                setData(r);
                // The line the server settled on becomes what the box shows, so
                // editing it starts from the file's own rather than from blank.
                setSpecDraft(r.Columns);
            })
            .catch(e => setError(String(e)))
            .finally(() => setBusy(false));
    }, []);

    React.useEffect(() => { load(file, spec); }, [file, spec, load]);

    const rows: ColumnRow[] = React.useMemo(() => {
        const all = data?.Rows || [];
        if (!sortOn || !data?.Spec) return all;
        const s = data.Spec[sortOn.col];
        return sortWithinParents(all, sortOn.col, sortOn.dir, !!s && s.Numbers !== '');
    }, [data, sortOn]);

    const hidden = React.useMemo(() => hiddenRows(rows, folded), [rows, folded]);
    const visible = React.useMemo(() => rows.filter(r => !hidden.has(r.Hash)), [rows, hidden]);

    const toggleFold = (hash: string) => {
        setFolded(prev => {
            const next = new Set(prev);
            if (next.has(hash)) next.delete(hash); else next.add(hash);
            return next;
        });
    };
    const foldAll = () => setFolded(new Set(foldableRows(rows)));
    const unfoldAll = () => setFolded(new Set());

    // Every write goes through an endpoint that already existed, and the view is
    // read back afterwards rather than patched in place. A rollup is of the whole
    // subtree, so one edited estimate changes the cell above it, and the one
    // above that - patching locally would mean saying the rollup rule a second
    // time in the browser and getting to keep both versions in step.
    const commit = async (row: ColumnRow, col: number, value: string | null) => {
        setEditing(null);
        if (value === null || !data?.Spec) return;
        const s = data.Spec[col];
        const cell = row.Cells[col];
        if (value === editValue(cell)) return;
        setSaving(true);
        try {
            if (s.Kind === 'property') {
                await ODb.changeProperty(row.Hash, s.Property, value);
            } else if (s.Kind === 'todo') {
                await ODb.changeStatus(row.Hash, value);
            } else if (s.Kind === 'item') {
                await ODb.renameHeadline(row.Hash, value);
            }
            load(file, spec);
        } catch (e) {
            setError(String(e));
        } finally {
            setSaving(false);
        }
    };

    const saveSpecToFile = async () => {
        if (!file) return;
        setSaving(true);
        try {
            const r = await ODb.setFileColumns(file, specDraft);
            if (r && r.Ok === false) { setError(r.Msg || 'could not write the columns line'); }
            else {
                // Written to the file, so the override is no longer needed - and
                // leaving it on would hide the next change anybody made in the
                // file itself.
                setSpec('');
                load(file, '');
            }
        } catch (e) {
            setError(String(e));
        } finally {
            setSaving(false);
        }
    };

    const headerCell = (s: ColumnSpec, i: number) => {
        const sorted = sortOn?.col === i;
        const summed = s.Summary !== '' || s.Property === 'CLOCKSUM' || s.Property === 'CLOCKSUM_T';
        return (
            <th
                key={`${s.Property}-${i}`}
                style={{
                    width: i === 0 ? undefined : columnWidth(s),
                    minWidth: i === 0 ? 240 : 80,
                    cursor: 'pointer', whiteSpace: 'nowrap',
                }}
                onClick={() => setSortOn(prev =>
                    prev?.col === i
                        ? (prev.dir === 'asc' ? { col: i, dir: 'desc' } : null)
                        : { col: i, dir: 'asc' })}
            >
                <Tooltip
                    size="sm" enterDelay={500}
                    title={
                        summed
                            ? `${s.Property} — parents show the total of everything under them`
                            : `${s.Property}${isEditable(s) ? ' — click a cell to edit it' : ' — worked out, not editable'}`
                    }
                >
                    <Box sx={{ display: 'inline-flex', alignItems: 'center', gap: 0.5 }}>
                        <Typography level="body-xs" sx={{ fontWeight: 'lg' }}>{s.Title}</Typography>
                        {summed && (
                            <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>Σ</Typography>
                        )}
                        {sorted && (sortOn!.dir === 'asc'
                            ? <ArrowUpwardIcon sx={{ fontSize: 12 }} />
                            : <ArrowDownwardIcon sx={{ fontSize: 12 }} />)}
                    </Box>
                </Tooltip>
            </th>
        );
    };

    const itemCell = (row: ColumnRow, s: ColumnSpec, i: number) => {
        const open = editing?.hash === row.Hash && editing?.col === i;
        return (
            <td key={i} style={{ maxWidth: columnWidth(s) }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.25, pl: `${(row.Level - 1) * 16}px` }}>
                    {row.HasChildren ? (
                        <IconButton
                            size="sm" variant="plain" color="neutral"
                            onClick={() => toggleFold(row.Hash)}
                            sx={{ '--IconButton-size': '18px', minWidth: 18 }}
                        >
                            {folded.has(row.Hash)
                                ? <ChevronRightIcon sx={{ fontSize: 15 }} />
                                : <ExpandMoreIcon sx={{ fontSize: 15 }} />}
                        </IconButton>
                    ) : <Box sx={{ width: 18, flex: '0 0 18px' }} />}
                    {open ? (
                        <PropertyEditor
                            spec={{ ...s, Allowed: null }}
                            cell={row.Cells[i]}
                            onDone={v => commit(row, i, v)}
                        />
                    ) : (
                        <Typography
                            level="body-sm"
                            onClick={() => isEditable(s) && setEditing({ hash: row.Hash, col: i })}
                            sx={{
                                cursor: isEditable(s) ? 'text' : 'default',
                                fontWeight: row.HasChildren ? 'lg' : 'md',
                                overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                            }}
                        >
                            {row.Cells[i].Value || <span style={{ opacity: 0.4 }}>(untitled)</span>}
                        </Typography>
                    )}
                    <Tooltip size="sm" enterDelay={500} title="open the file here">
                        <IconButton
                            size="sm" variant="plain" color="neutral"
                            onClick={() => nav.toFile({
                                filename: data!.File, line: row.LineNum,
                                back: { app: 'Columns', label: 'Back to columns' },
                            })}
                            sx={{ '--IconButton-size': '18px', ml: 0.25, opacity: 0.35, '&:hover': { opacity: 1 } }}
                        >
                            <OpenInFileIcon sx={{ fontSize: 13 }} />
                        </IconButton>
                    </Tooltip>
                </Box>
            </td>
        );
    };

    const valueCell = (row: ColumnRow, s: ColumnSpec, i: number) => {
        const cell = row.Cells[i];
        const open = editing?.hash === row.Hash && editing?.col === i;
        if (s.Kind === 'todo') {
            return (
                <td key={i}><StatusEditor row={row} onPick={v => commit(row, i, v)} /></td>
            );
        }
        if (open && s.Kind === 'property') {
            return (
                <td key={i}>
                    <PropertyEditor spec={s} cell={cell} onDone={v => commit(row, i, v)} />
                </td>
            );
        }
        // A summed value is drawn differently on purpose: it is the one number in
        // the table that nobody typed, and a total that looks like an entry
        // invites somebody to correct it on the wrong heading.
        const body = (
            <Typography
                level="body-xs"
                sx={{
                    fontFamily: s.Numbers ? 'monospace' : undefined,
                    color: cell.Summed ? 'primary.plainColor' : (cell.Value ? 'text.primary' : 'text.tertiary'),
                    fontStyle: cell.Summed ? 'italic' : undefined,
                    cursor: isEditable(s) ? 'text' : 'default',
                    whiteSpace: 'nowrap',
                }}
                onClick={() => isEditable(s) && setEditing({ hash: row.Hash, col: i })}
            >
                {cell.Value || (isEditable(s) ? '—' : '')}
            </Typography>
        );
        if (!cell.Summed) return <td key={i}>{body}</td>;
        return (
            <td key={i}>
                <Tooltip
                    size="sm" enterDelay={300}
                    title={cell.Own
                        ? `${cell.Value} in total — ${cell.Own} of it on this heading itself`
                        : `${cell.Value} in total, all of it from what is underneath`}
                >
                    <Box sx={{ display: 'inline-block' }}>{body}</Box>
                </Tooltip>
            </td>
        );
    };

    const specIsFileOwn = data ? specDraft === data.Columns && data.From === 'file' : false;

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%', gap: 1, p: 1, minHeight: 0 }}>
            <Sheet variant="outlined" sx={{ p: 1, borderRadius: 'sm', display: 'flex', flexWrap: 'wrap', gap: 1, alignItems: 'center' }}>
                <Autocomplete
                    size="sm"
                    placeholder="pick a file"
                    options={files}
                    value={file || null}
                    onChange={(_, v) => { setFile((v as string) || ''); setFolded(new Set()); setSortOn(null); setSpec(''); }}
                    getOptionLabel={o => baseName(o as string)}
                    sx={{ minWidth: 220 }}
                />
                <Input
                    size="sm"
                    placeholder="%25ITEM %TODO %EFFORT{:}"
                    value={specDraft}
                    onChange={e => setSpecDraft(e.target.value)}
                    onKeyDown={e => { if (e.key === 'Enter') setSpec(specDraft); }}
                    sx={{ flex: '1 1 320px', fontFamily: 'monospace', fontSize: 12 }}
                    endDecorator={
                        <Box sx={{ display: 'flex', gap: 0.5 }}>
                            <Button size="sm" variant="plain" onClick={() => setSpec(specDraft)}>Apply</Button>
                            <Tooltip size="sm" title="write this as the file's own #+COLUMNS: line">
                                <Button size="sm" variant="plain" disabled={!file || saving} onClick={saveSpecToFile}>
                                    Save
                                </Button>
                            </Tooltip>
                        </Box>
                    }
                />
                {data && (
                    <Tooltip
                        size="sm"
                        title={{
                            file: "the file's own #+COLUMNS: line",
                            config: 'the server default — this file declares no #+COLUMNS: line',
                            request: 'the line you typed, for this view only',
                            heading: "a heading's own :COLUMNS: property",
                        }[data.From] || data.From}
                    >
                        <Chip size="sm" variant="soft" color={data.From === 'file' ? 'success' : 'neutral'}>
                            {data.From}
                        </Chip>
                    </Tooltip>
                )}
                {specIsFileOwn || !data ? null : (
                    <Tooltip size="sm" title="back to the file's own line">
                        <IconButton size="sm" variant="plain" onClick={() => { setSpec(''); setSpecDraft(data.Columns); }}>
                            <RestartAltIcon />
                        </IconButton>
                    </Tooltip>
                )}
                <Box sx={{ display: 'flex', gap: 0.5, ml: 'auto' }}>
                    <Tooltip size="sm" title="fold every branch"><IconButton size="sm" variant="plain" onClick={foldAll}><UnfoldLessIcon /></IconButton></Tooltip>
                    <Tooltip size="sm" title="open every branch"><IconButton size="sm" variant="plain" onClick={unfoldAll}><UnfoldMoreIcon /></IconButton></Tooltip>
                    <Tooltip size="sm" title="read it again"><IconButton size="sm" variant="plain" onClick={() => load(file, spec)}><RefreshIcon /></IconButton></Tooltip>
                    {(busy || saving) && <CircularProgress size="sm" />}
                </Box>
            </Sheet>

            {error !== '' && <Alert size="sm" color="danger" variant="soft">{error}</Alert>}

            {!file && (
                <Alert size="sm" variant="soft" color="neutral">
                    Pick a file. Its headings are drawn as org's column view, and any column
                    whose spec carries a summary operator — <code>{'%EFFORT{:}'}</code> — shows
                    the total of everything underneath on each parent.
                </Alert>
            )}

            {data && data.Spec && (
                <Sheet variant="outlined" sx={{ flex: 1, minHeight: 0, overflow: 'auto', borderRadius: 'sm' }}>
                    <Table
                        size="sm" stickyHeader hoverRow
                        sx={{
                            '--TableCell-paddingY': '3px',
                            '& thead th': { verticalAlign: 'bottom' },
                            '& td': { verticalAlign: 'middle' },
                        }}
                    >
                        <thead><tr>{data.Spec.map(headerCell)}</tr></thead>
                        <tbody>
                            {visible.map(row => (
                                <tr key={row.Hash}>
                                    {data.Spec!.map((s, i) =>
                                        i === 0 && s.Kind === 'item'
                                            ? itemCell(row, s, i)
                                            : valueCell(row, s, i))}
                                </tr>
                            ))}
                            {visible.length === 0 && (
                                <tr><td colSpan={data.Spec.length}>
                                    <Typography level="body-sm" sx={{ color: 'text.tertiary', p: 1 }}>
                                        This file has no headings.
                                    </Typography>
                                </td></tr>
                            )}
                        </tbody>
                    </Table>
                </Sheet>
            )}
        </Box>
    );
}
