// The raw org file, coloured the way an editor would colour it.
//
// This is a highlighter rather than a parser: it walks the file a line at a
// time, decides what kind of line it is looking at, and splits that line into
// spans. Nothing here builds a tree, because nothing downstream needs one - the
// file view only wants the text back with colour on it.
//
// The two things that do carry across lines are blocks (#+BEGIN_SRC ... #+END)
// and drawers (:PROPERTIES: ... :END:), both of which change how the lines
// inside them are read, so the walk keeps that much state.

import * as React from 'react';
import Box from '@mui/joy/Box';
import { useColorScheme } from '@mui/joy/styles';
import { orgPalette } from '../orgtheme';
import { hlLine, langSpec, newHlState, isKnownLang, KIND_ROLE, HlState } from '../codehl';
import { useSetting } from '../useSettings';

// ---------------------------------------------------------------------------
// Todo keywords
// ---------------------------------------------------------------------------

// What the server hands out when a file says nothing, from defaultTodoStates in
// settings.go. A file's own #+TODO:/#+SEQ_TODO:/#+TYP_TODO: line replaces it,
// which is why the keywords are read off the text rather than fixed here.
export const DEFAULT_TODO_STATES = 'TODO INPROGRESS IN-PROGRESS NEXT BLOCKED PAUSED WAITING PHONE MEETING BACKLOG | DONE CANCELLED';

export type TodoStates = { active: Set<string>; done: Set<string> };

// "TODO NEXT | DONE CANCELLED" - everything after the bar is a finished state,
// and with no bar the last word is the finished one, as org itself has it.
function parseTodoStates(spec: string): { active: string[]; done: string[] } {
    const words = spec
        .split(/\s+/)
        .map(w => w.replace(/\([^)]*\)$/, '')) // TODO(t) - the key is not part of the name
        .filter(w => w !== '');
    const bar = words.indexOf('|');
    if (bar >= 0) return { active: words.slice(0, bar), done: words.slice(bar + 1) };
    if (words.length === 0) return { active: [], done: [] };
    return { active: words.slice(0, -1), done: words.slice(-1) };
}

// The keywords this file uses: the defaults, plus anything its own #+TODO lines
// declare. They add rather than replace so that a file declaring one extra
// sequence does not lose the states the server would still accept.
export function todoStates(text: string): TodoStates {
    const active = new Set<string>();
    const done = new Set<string>();
    const add = (spec: string) => {
        const p = parseTodoStates(spec);
        p.active.forEach(w => active.add(w));
        p.done.forEach(w => done.add(w));
    };
    add(DEFAULT_TODO_STATES);
    const re = /^#\+(?:TODO|SEQ_TODO|TYP_TODO):(.*)$/gim;
    let m: RegExpExecArray | null;
    while ((m = re.exec(text)) !== null) add(m[1]);
    // A state named on both sides of two different sequences is finished: the
    // heading is done, whatever else some other sequence calls it.
    done.forEach(w => active.delete(w));
    return { active, done };
}

// ---------------------------------------------------------------------------
// The palette
// ---------------------------------------------------------------------------

// Heading levels run through these palette roles and then wrap, so a seventh
// level of outline is coloured like the first rather than going uncoloured.
const HEADING_COLORS = ['h1', 'h2', 'h3', 'h4', 'h5', 'h6'];

// The palettes now live in orgtheme.ts, where a scheme is written down as the
// handful of colours its authors published and the org roles are derived from
// those. Two hand-maintained palettes were fine; eleven would not have been.

// ---------------------------------------------------------------------------
// Tokens
// ---------------------------------------------------------------------------

export type Tok = {
    c: string;           // palette key
    s: string;           // the text itself
    bold?: boolean;
    italic?: boolean;
    underline?: boolean;
    strike?: boolean;
};

function push(out: Tok[], c: string, s: string, extra?: Partial<Tok>) {
    if (s === '') return;
    out.push({ c, s, ...(extra || {}) });
}

// ---------------------------------------------------------------------------
// Inline markup
// ---------------------------------------------------------------------------

// A timestamp in either bracket, with everything org allows after the date:
// a day name, a time or time range, a repeater and a warning period.
const TS = /([[<])(\d{4}-\d{2}-\d{2})([^\]>\n]*)([\]>])(--)?/;

// [[target][description]] or [[target]]. The target is lazy so that a
// description holding a ] does not swallow the end of the link.
const LINK = /\[\[([^\]]*?)\](?:\[([^\]]*?)\])?\]/;

// *bold* /italic/ _under_ +strike+ =verbatim= ~code~. Org wants the marker to
// start at a word boundary and end at one, which is what keeps a/b and 3*4 from
// turning into markup, so the surroundings are part of the match.
const EMPH = /(^|[\s(['"{\-])([*/_+=~])([^\s](?:[^\n]*?[^\s])?)\2(?=$|[\s.,:;!?')\]}"\-])/;

const EMPH_STYLE: Record<string, { c: string; extra: Partial<Tok> }> = {
    '*': { c: 'bold', extra: { bold: true } },
    '/': { c: 'italic', extra: { italic: true } },
    '_': { c: 'underline', extra: { underline: true } },
    '+': { c: 'strike', extra: { strike: true } },
    '=': { c: 'verbatim', extra: {} },
    '~': { c: 'code', extra: {} },
};

// A footnote reference or definition: [fn:1], [fn:name: inline text].
const FOOTNOTE = /\[fn:[^\]\s]*/;

// Everything that can appear inside running text - a heading title, a list
// item, a table cell, a paragraph. `base` is the colour text with nothing on it
// gets, so the same routine can run over a heading (coloured by level) and over
// body text (plain) without either losing its ground colour.
function inline(text: string, base: string, out: Tok[], baseExtra?: Partial<Tok>) {
    let rest = text;
    let guard = 0;
    while (rest !== '' && guard++ < 4000) {
        const link = LINK.exec(rest);
        const ts = TS.exec(rest);
        const emph = EMPH.exec(rest);
        const fn = FOOTNOTE.exec(rest);

        // Whichever comes first wins, so that a timestamp inside a link
        // description is not pulled out from under it.
        let best: { at: number; kind: string } | null = null;
        const consider = (m: RegExpExecArray | null, kind: string) => {
            if (m === null) return;
            if (best === null || m.index < best.at) best = { at: m.index, kind };
        };
        consider(link, 'link');
        consider(ts, 'ts');
        consider(emph, 'emph');
        consider(fn, 'fn');
        if (best === null) break;
        const at: number = (best as { at: number; kind: string }).at;
        const kind: string = (best as { at: number; kind: string }).kind;

        push(out, base, rest.slice(0, at), baseExtra);

        if (kind === 'link' && link !== null) {
            push(out, 'linkPunct', '[[');
            push(out, 'linkTarget', link[1]);
            if (link[2] !== undefined) {
                push(out, 'linkPunct', '][');
                push(out, 'linkDesc', link[2]);
            }
            push(out, 'linkPunct', ']]');
            rest = rest.slice(at + link[0].length);
            continue;
        }
        if (kind === 'ts' && ts !== null) {
            const c = ts[1] === '<' ? 'tsActive' : 'tsInactive';
            push(out, c, ts[0]);
            rest = rest.slice(at + ts[0].length);
            continue;
        }
        if (kind === 'fn' && fn !== null) {
            push(out, 'footnote', fn[0]);
            rest = rest.slice(at + fn[0].length);
            continue;
        }
        if (kind === 'emph' && emph !== null) {
            const style = EMPH_STYLE[emph[2]];
            push(out, base, emph[1], baseExtra);
            push(out, 'markup', emph[2]);
            push(out, style.c, emph[3], style.extra);
            push(out, 'markup', emph[2]);
            rest = rest.slice(at + emph[0].length);
            continue;
        }
        break;
    }
    push(out, base, rest, baseExtra);
}

// ---------------------------------------------------------------------------
// Lines
// ---------------------------------------------------------------------------

export const HEADING = /^(\*+)(\s+)(.*)$/;
const KEYWORD = /^(\s*)(#\+[A-Za-z0-9_@-]+:?)(.*)$/;
const BLOCK_BEGIN = /^(\s*)(#\+(?:BEGIN|begin)_([A-Za-z0-9_-]+))(.*)$/;
const BLOCK_END = /^(\s*)(#\+(?:END|end)_([A-Za-z0-9_-]+))\s*$/;
const DRAWER_OPEN = /^(\s*)(:[A-Za-z0-9_@#%-]+:)\s*$/;
const DRAWER_END = /^(\s*):(?:END|end):\s*$/;
const PROPERTY = /^(\s*)(:[A-Za-z0-9_@#%+-]+:)(\s*)(.*)$/;
const PLANNING = /^(\s*)((?:SCHEDULED|DEADLINE|CLOSED|CLOCK):)(.*)$/;
const LIST = /^(\s*)([-+*]|\d+[.)])(\s+)(.*)$/;
const CHECKBOX = /^(\[[ xX-]\])(\s*)/;
const TABLE_RULE = /^(\s*)(\|[-+|]*)\s*$/;
const TABLE_ROW = /^(\s*)(\|.*)$/;
const HRULE = /^(\s*)(-{5,})\s*$/;
const COMMENT = /^(\s*)(#(?:\s.*|)?)$/;
const TAGS = /\s+(:(?:[^\s:]+:)+)$/;
const PRIORITY = /^(\[#[A-Za-z0-9]\])(\s*)/;

// The lines of a block whose body is not org: source, example, export, verse.
// Quote and center hold org markup and are left to the normal walk.
const OPAQUE_BLOCKS = new Set(['src', 'example', 'export', 'verse', 'ascii', 'comment']);

// One line of the file as the spans it is made of.
export function lineTokens(
    line: string, st: TodoStates, inBlock: string, inDrawer: boolean,
    lang: string = '', code?: HlState,
): Tok[] {
    const out: Tok[] = [];

    // Inside a source or example block nothing is org, so only the closing
    // delimiter is looked for. A *source* block in a language we know is then
    // handed to the code scanner and painted out of this theme's own colours;
    // anything else - an example, an export, a language nobody wrote a spec
    // for - is left as one span rather than half coloured by guesswork.
    if (inBlock !== '' && OPAQUE_BLOCKS.has(inBlock)) {
        const end = BLOCK_END.exec(line);
        if (end !== null && end[3].toLowerCase() === inBlock) {
            push(out, 'fg', end[1]);
            push(out, 'blockDelim', end[2]);
            return out;
        }
        if (inBlock === 'src' && isKnownLang(lang)) {
            const state = code ? { ...code } : newHlState();
            for (const span of hlLine(line, langSpec(lang), state)) {
                push(out, KIND_ROLE[span.kind], span.text);
            }
            return out;
        }
        push(out, 'blockBody', line);
        return out;
    }

    const heading = HEADING.exec(line);
    if (heading !== null) {
        const level = heading[1].length;
        const color = HEADING_COLORS[(level - 1) % HEADING_COLORS.length];
        push(out, 'stars', heading[1]);
        push(out, 'fg', heading[2]);

        let title = heading[3];

        // Tags first, off the end, so the title that is left is just the title.
        let tagPart = '';
        const tags = TAGS.exec(title);
        if (tags !== null) {
            tagPart = title.slice(tags.index);
            title = title.slice(0, tags.index);
        }

        // Then the keyword and priority off the front.
        const first = /^([A-Za-z][A-Za-z0-9_@-]*)(\s+|$)/.exec(title);
        if (first !== null && (st.active.has(first[1]) || st.done.has(first[1]))) {
            push(out, st.done.has(first[1]) ? 'doneKw' : 'todo', first[1], { bold: true });
            push(out, 'fg', first[2]);
            title = title.slice(first[0].length);
        }
        if (title.startsWith('COMMENT ')) {
            push(out, 'comment', 'COMMENT ', { bold: true });
            title = title.slice('COMMENT '.length);
        }
        const prio = PRIORITY.exec(title);
        if (prio !== null) {
            push(out, 'priority', prio[1], { bold: true });
            push(out, 'fg', prio[2]);
            title = title.slice(prio[0].length);
        }

        inline(title, color, out, { bold: true });
        if (tagPart !== '') {
            const lead = /^\s*/.exec(tagPart);
            push(out, 'fg', lead ? lead[0] : '');
            push(out, 'tag', tagPart.trimStart());
        }
        return out;
    }

    // A drawer's own lines. :PROPERTIES: has been opened by the walk, so
    // anything of the form :KEY: value inside one is a property.
    const drawerEnd = DRAWER_END.exec(line);
    if (drawerEnd !== null) {
        push(out, 'fg', drawerEnd[1]);
        push(out, 'drawer', line.trimStart());
        return out;
    }
    const drawerOpen = DRAWER_OPEN.exec(line);
    if (drawerOpen !== null) {
        push(out, 'fg', drawerOpen[1]);
        push(out, 'drawer', drawerOpen[2]);
        return out;
    }
    if (inDrawer) {
        const prop = PROPERTY.exec(line);
        if (prop !== null) {
            push(out, 'fg', prop[1]);
            push(out, 'propKey', prop[2]);
            push(out, 'fg', prop[3]);
            inline(prop[4], 'propVal', out);
            return out;
        }
    }

    const planning = PLANNING.exec(line);
    if (planning !== null) {
        push(out, 'fg', planning[1]);
        push(out, 'planning', planning[2], { bold: true });
        inline(planning[3], 'fg', out);
        return out;
    }

    const begin = BLOCK_BEGIN.exec(line);
    if (begin !== null) {
        push(out, 'fg', begin[1]);
        push(out, 'blockDelim', begin[2]);
        push(out, 'keywordArg', begin[4]);
        return out;
    }
    const end = BLOCK_END.exec(line);
    if (end !== null) {
        push(out, 'fg', end[1]);
        push(out, 'blockDelim', end[2]);
        return out;
    }

    const comment = COMMENT.exec(line);
    if (comment !== null) {
        push(out, 'fg', comment[1]);
        push(out, 'comment', comment[2]);
        return out;
    }

    const keyword = KEYWORD.exec(line);
    if (keyword !== null) {
        push(out, 'fg', keyword[1]);
        push(out, 'keyword', keyword[2]);
        push(out, 'keywordArg', keyword[3]);
        return out;
    }

    const hrule = HRULE.exec(line);
    if (hrule !== null) {
        push(out, 'fg', hrule[1]);
        push(out, 'rule', line.trimStart());
        return out;
    }

    const tableRule = TABLE_RULE.exec(line);
    if (tableRule !== null) {
        push(out, 'fg', tableRule[1]);
        push(out, 'tableRule', line.trimStart());
        return out;
    }
    const tableRow = TABLE_ROW.exec(line);
    if (tableRow !== null) {
        push(out, 'fg', tableRow[1]);
        // The bars are the table; what sits between them is ordinary text.
        const cells = tableRow[2].split('|');
        for (let i = 0; i < cells.length; i++) {
            if (i > 0) push(out, 'table', '|');
            inline(cells[i], 'fg', out);
        }
        return out;
    }

    const list = LIST.exec(line);
    if (list !== null) {
        push(out, 'fg', list[1]);
        push(out, 'bullet', list[2], { bold: true });
        push(out, 'fg', list[3]);
        let body = list[4];
        const box = CHECKBOX.exec(body);
        if (box !== null) {
            push(out, box[1] === '[ ]' ? 'checkOpen' : 'checkDone', box[1], { bold: true });
            push(out, 'fg', box[2]);
            body = body.slice(box[0].length);
        }
        // "term :: description" - the term is what the eye is looking for.
        const dt = /^(.+?)\s+::\s/.exec(body);
        if (dt !== null) {
            inline(dt[1], 'fg', out, { bold: true });
            push(out, 'markup', body.slice(dt[1].length, dt[0].length));
            body = body.slice(dt[0].length);
        }
        inline(body, 'fg', out);
        return out;
    }

    inline(line, 'fg', out);
    return out;
}

// The block and drawer state a line is read in, worked out once for the file.
export type LineState = {
    block: string;
    drawer: boolean;
    // The language of the source block this line is inside, and where the
    // code scanner had got to when it reached this line. Carried per line
    // rather than worked out as the lines are painted, because the file is
    // painted a screenful at a time and in fold order - a scanner run over
    // what happens to be on screen would start a python file in the middle of
    // a docstring and colour the rest of it as prose.
    lang: string;
    code: HlState;
};

export function walk(lines: string[]): LineState[] {
    const states: LineState[] = [];
    let block = '';
    let drawer = false;
    let lang = '';
    let code = newHlState();
    let spec = langSpec('');
    for (const line of lines) {
        states.push({ block, drawer, lang, code: { ...code } });
        if (block !== '') {
            const end = BLOCK_END.exec(line);
            if (end !== null && end[3].toLowerCase() === block) {
                block = '';
                lang = '';
                code = newHlState();
            } else if (block === 'src' && lang !== '') {
                // Run the scanner over the line for its side effect on the
                // state; what it produces is worked out again when the line is
                // painted, which costs one pass over a line of code and saves
                // keeping a span list per line of the file.
                hlLine(line, spec, code);
            }
            continue;
        }
        const begin = BLOCK_BEGIN.exec(line);
        if (begin !== null) {
            block = begin[3].toLowerCase();
            lang = block === 'src' ? (begin[4] || '').trim().split(/\s+/)[0].toLowerCase() : '';
            code = newHlState();
            spec = langSpec(lang);
            continue;
        }
        if (drawer) {
            if (DRAWER_END.test(line) || HEADING.test(line)) drawer = false;
            continue;
        }
        if (DRAWER_OPEN.test(line) && !DRAWER_END.test(line)) drawer = true;
    }
    return states;
}

// ---------------------------------------------------------------------------
// Folding
// ---------------------------------------------------------------------------
//
// The highlighter builds no tree, and it still does not: folding needs to know
// where a heading's subtree ends and where a drawer closes, which is two flat
// scans over lines it has already classified rather than a parse.
//
// A heading cycles the way org's TAB does - the whole subtree hidden, then the
// headline with its direct children under it, then everything - and a drawer is
// simply shut or open. Drawers start shut because a property drawer is
// bookkeeping: it is there to be read when it is wanted, not every time the
// file is opened.

export type FoldState = 'folded' | 'children' | 'subtree' | 'open';

export interface Region {
    kind: 'heading' | 'drawer';
    // The line the region is headed by, and the last line it covers.
    start: number;
    end: number;
    // Heading depth; drawers have none.
    level: number;
    // The headings directly under this one, by line. Empty for a drawer and for
    // a heading with nothing but body text under it.
    children: number[];
}

// Every line that can be folded, by the line it is headed by. A heading with
// nothing under it is left out: a fold marker on a line that hides nothing is
// a promise the view cannot keep.
export function outline(lines: string[], states: LineState[]): Map<number, Region> {
    const out = new Map<number, Region>();
    const heads: { line: number; level: number }[] = [];
    for (let i = 0; i < lines.length; i++) {
        // A line of stars inside a source block is not a heading, which is why
        // this reads the block state the walk already worked out.
        if (states[i].block !== '') continue;
        const h = HEADING.exec(lines[i]);
        if (h !== null) heads.push({ line: i, level: h[1].length });
    }

    for (let k = 0; k < heads.length; k++) {
        const { line, level } = heads[k];
        let end = lines.length - 1;
        for (let j = k + 1; j < heads.length; j++) {
            if (heads[j].level <= level) { end = heads[j].line - 1; break; }
        }
        if (end <= line) continue;
        // Nothing but blank lines under it is nothing to hide: a file that ends
        // in a newline would otherwise give its last heading a fold marker that
        // swallows one empty line and looks broken.
        let anything = false;
        for (let j = line + 1; j <= end; j++) if (lines[j].trim() !== '') { anything = true; break; }
        if (!anything) continue;
        // The direct children are the shallowest headings inside the subtree -
        // shallowest rather than "level + 1", because org does not mind a file
        // that goes from one star to three and neither should this.
        const inside = heads.filter(x => x.line > line && x.line <= end);
        const childLevel = inside.reduce((m, x) => Math.min(m, x.level), Infinity);
        const children = inside.filter(x => x.level === childLevel).map(x => x.line);
        out.set(line, { kind: 'heading', start: line, end, level, children });
    }

    for (let i = 0; i < lines.length; i++) {
        if (states[i].block !== '' || states[i].drawer) continue;
        if (!DRAWER_OPEN.test(lines[i]) || DRAWER_END.test(lines[i])) continue;
        let end = -1;
        for (let j = i + 1; j < lines.length; j++) {
            // A heading closes an unterminated drawer, the same way the walk
            // has it - an org file with a missing :END: should not swallow the
            // rest of itself.
            if (DRAWER_END.test(lines[j])) { end = j; break; }
            if (states[j].block === '' && HEADING.test(lines[j])) { end = j - 1; break; }
        }
        if (end < 0) end = lines.length - 1;
        if (end <= i) continue;
        out.set(i, { kind: 'drawer', start: i, end, level: 0, children: [] });
    }
    return out;
}

// What a region is doing when nobody has said otherwise.
export function defaultFold(r: Region): FoldState {
    return r.kind === 'drawer' ? 'folded' : 'subtree';
}

// The next state round the cycle. Headings go the way org's TAB goes; a drawer
// has only the two.
export function nextFold(r: Region, now: FoldState): FoldState {
    if (r.kind === 'drawer') return now === 'folded' ? 'open' : 'folded';
    if (now === 'folded') return r.children.length > 0 ? 'children' : 'subtree';
    if (now === 'children') return 'subtree';
    return 'folded';
}

// Which lines are out of sight. Every region hides its own range and the union
// is taken, so a heading folded round an open drawer still hides the drawer -
// nesting falls out of it rather than having to be walked.
export function hiddenLines(
    total: number,
    regions: Map<number, Region>,
    folds: Map<number, FoldState>,
    // What a region does when nobody has said otherwise. The file view starts
    // drawers shut, because a file of headings each with a property drawer is
    // mostly drawer; a preview of four lines starts everything open, because
    // what is *in* the drawer is the thing being checked.
    whenUnsaid: (r: Region) => FoldState = defaultFold,
): boolean[] {
    const hidden = new Array<boolean>(total).fill(false);
    const hide = (from: number, to: number) => {
        for (let i = Math.max(from, 0); i <= to && i < total; i++) hidden[i] = true;
    };

    // Headings are walked from the outside in, a parent handing each child the
    // run of lines it owns and then letting the child say what happens inside
    // it. They cannot simply each hide their own range and have the results
    // added up: a parent showing CHILDREN would then be hiding everything but
    // the child headlines, and a child opened inside it could never show
    // anything - its arrow turned but nothing appeared.
    const headings: Region[] = [];
    regions.forEach(r => { if (r.kind === 'heading') headings.push(r); });
    headings.sort((a, b) => a.start - b.start);

    const visit = (r: Region) => {
        const state = folds.get(r.start) ?? whenUnsaid(r);
        if (state === 'folded') { hide(r.start + 1, r.end); return; }

        // Where each child's run of lines begins and ends. Taken from the
        // children themselves rather than from their regions, because a child
        // with nothing under it has no region and still owns its line.
        const kids = r.children.slice().sort((a, b) => a - b);
        const kidEnd = (i: number) => (i + 1 < kids.length ? kids[i + 1] - 1 : r.end);

        if (state === 'children') {
            // Only the heading's *own* body goes - the part before the first
            // child. What happens inside each child is the child's business.
            hide(r.start + 1, (kids.length > 0 ? kids[0] : r.end + 1) - 1);
        }

        kids.forEach((k, i) => {
            const kr = regions.get(k);
            if (kr) { visit(kr); return; }
            // A child with no region of its own has nothing under it but blank
            // lines; under CHILDREN they go with the rest of the padding.
            if (state === 'children') hide(k + 1, kidEnd(i));
        });
    };

    // The outermost headings: anything not already inside one that came before.
    let coveredTo = -1;
    for (const h of headings) {
        if (h.start <= coveredTo) continue;
        coveredTo = h.end;
        visit(h);
    }

    // Drawers are added on top rather than walked. A drawer inside something
    // already hidden is hidden twice, which costs nothing, and one that is on
    // screen answers only for itself.
    regions.forEach(r => {
        if (r.kind !== 'drawer') return;
        const state = folds.get(r.start) ?? whenUnsaid(r);
        if (state === 'folded') hide(r.start + 1, r.end);
    });
    return hidden;
}

// ---------------------------------------------------------------------------
// The view
// ---------------------------------------------------------------------------

// A file long enough that painting all of it at once is felt is painted a
// screenful at a time instead, growing as it is scrolled.
const CHUNK = 600;

export default function OrgSource({
    text,
    wrap = false,
    scrollTo = '',
    scrollToLine = -1,
    openDrawers = false,
}: {
    text: string;
    wrap?: boolean;
    // A heading to scroll to and flash, by its text - what a link followed into
    // this file was pointing at.
    scrollTo?: string;
    // The same, by line, zero based. Takes precedence over the text, because
    // it is exact where the text is not: two headings in one file can read the
    // same, and a jump from a search result knows which one it meant.
    scrollToLine?: number;
    // Start with the drawers open. For a short preview, where the values in
    // the drawer are what somebody is checking rather than clutter in the way
    // of the prose.
    openDrawers?: boolean;
}) {
    const { mode, systemMode } = useColorScheme();
    const dark = (mode === 'system' ? systemMode : mode) !== 'light';
    const [themeKey] = useSetting('orgTheme');
    const p = orgPalette(themeKey, dark);

    const lines = React.useMemo(() => text.replace(/\r\n/g, '\n').split('\n'), [text]);
    const st = React.useMemo(() => todoStates(text), [text]);
    const states = React.useMemo(() => walk(lines), [lines]);

    // The line the link came in on, or -1. Looked for over the whole file even
    // though only the first chunk is painted, so that the chunk it is in can be
    // painted before it is scrolled to.
    const target = React.useMemo(() => {
        if (scrollToLine >= 0 && scrollToLine < lines.length) return scrollToLine;
        const want = scrollTo.trim().toLowerCase();
        if (want === '') return -1;
        let loose = -1;
        for (let i = 0; i < lines.length; i++) {
            const h = HEADING.exec(lines[i]);
            if (h === null) continue;
            const title = h[3].replace(TAGS, '').trim().toLowerCase();
            if (title === want) return i;
            if (loose < 0 && title.indexOf(want) >= 0) loose = i;
        }
        return loose;
    }, [lines, scrollTo, scrollToLine]);

    const regions = React.useMemo(() => outline(lines, states), [lines, states]);
    // Set only where the reader has said something; everything else takes its
    // default, which is how drawers manage to start shut without the file
    // having to be walked to put them there.
    const [folds, setFolds] = React.useState<Map<number, FoldState>>(new Map());
    React.useEffect(() => { setFolds(new Map()); }, [lines]);

    const hidden = React.useMemo(
        () => hiddenLines(lines.length, regions, folds,
            openDrawers ? (r: Region) => (r.kind === 'drawer' ? 'open' : 'subtree') : defaultFold),
        [lines.length, regions, folds, openDrawers],
    );
    // The lines actually on show, in order. Everything downstream counts in
    // these rather than in file lines, or folding a thousand-line subtree would
    // leave the chunking convinced it had already painted the file.
    const visible = React.useMemo(() => {
        const out: number[] = [];
        for (let i = 0; i < lines.length; i++) if (!hidden[i]) out.push(i);
        return out;
    }, [lines.length, hidden]);

    const cycle = React.useCallback((line: number) => {
        const r = regions.get(line);
        if (!r) return;
        setFolds(prev => {
            const next = new Map(prev);
            const now = prev.get(line) ?? defaultFold(r);
            const to = nextFold(r, now);
            next.set(line, to);
            // Going to CHILDREN shuts the children as it goes, so that what is
            // on screen is the headline and its children and nothing else -
            // whatever those children were left at last time.
            if (to === 'children') r.children.forEach(c => next.set(c, 'folded'));
            // Going to SUBTREE means the whole subtree, so whatever anything
            // inside was left at is forgotten rather than left to hold parts of
            // it shut. Forgetting rather than opening is what lets the drawers
            // in there fall back to shut, which is their default and the point
            // of having one.
            if (to === 'subtree') {
                regions.forEach((inner, at) => {
                    if (at > r.start && at <= r.end) next.delete(at);
                });
            }
            return next;
        });
    }, [regions]);

    const [shown, setShown] = React.useState(Math.min(lines.length, CHUNK));
    React.useEffect(() => {
        setShown(Math.min(lines.length, target >= 0 ? Math.max(target + CHUNK, CHUNK) : CHUNK));
    }, [lines, target]);

    const targetRef = React.useRef<HTMLDivElement | null>(null);
    React.useEffect(() => {
        const el = targetRef.current;
        if (el === null || target < 0) return;
        el.scrollIntoView({ block: 'start' });
        el.style.transition = 'background-color 1.2s';
        el.style.backgroundColor = 'rgba(255, 213, 79, 0.45)';
        const t = window.setTimeout(() => { el.style.backgroundColor = 'transparent'; }, 1400);
        return () => window.clearTimeout(t);
    }, [target, shown]);

    const onScroll = (e: React.UIEvent<HTMLDivElement>) => {
        if (shown >= visible.length) return;
        const el = e.currentTarget;
        if (el.scrollTop + el.clientHeight * 2 < el.scrollHeight) return;
        setShown(n => Math.min(visible.length, n + CHUNK));
    };

    const gutterWidth = `${String(lines.length).length + 1}ch`;

    return (
        <Box
            onScroll={onScroll}
            sx={{
                height: '100%',
                overflow: 'auto',
                bgcolor: p.bg,
                color: p.fg,
                fontFamily: '"SFMono-Regular", "JetBrains Mono", Consolas, "Liberation Mono", Menlo, monospace',
                fontSize: 13,
                lineHeight: 1.55,
                '& ::selection': { backgroundColor: p.selBg },
            }}
        >
            <Box component="pre" sx={{ m: 0, p: 0, fontFamily: 'inherit', fontSize: 'inherit', lineHeight: 'inherit' }}>
                {visible.slice(0, shown).map(i => {
                    const line = lines[i];
                    const region = regions.get(i);
                    const state = region ? (folds.get(i) ?? defaultFold(region)) : undefined;
                    const shut = state === 'folded' || state === 'children';
                    return (
                    <Box
                        key={i}
                        ref={i === target ? targetRef : undefined}
                        tabIndex={region ? 0 : undefined}
                        onKeyDown={region ? (e: React.KeyboardEvent) => {
                            // Tab cycles, the way it does in org. Shift+Tab is
                            // deliberately left alone: it is the only way back
                            // out of a long file with the keyboard, and a view
                            // that traps focus is worse than one that cannot
                            // cycle backwards.
                            if (e.key === 'Tab' && !e.shiftKey) { e.preventDefault(); cycle(i); }
                            else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); cycle(i); }
                        } : undefined}
                        sx={{
                            display: 'flex',
                            alignItems: 'flex-start',
                            outline: 'none',
                            '&:hover': { backgroundColor: p.selBg },
                            '&:focus-visible': { backgroundColor: p.selBg, boxShadow: `inset 2px 0 0 ${p.h1}` },
                        }}
                    >
                        <Box
                            component="span"
                            sx={{
                                flex: '0 0 auto',
                                width: gutterWidth,
                                pr: 1.25,
                                textAlign: 'right',
                                color: p.gutter,
                                bgcolor: p.gutterBg,
                                userSelect: 'none',
                                position: 'sticky',
                                left: 0,
                            }}
                        >
                            {i + 1}
                        </Box>
                        {/* The fold marker. Only on lines that really do hide
                            something, and it keeps its width on the ones that
                            do not so the text stays in one column. */}
                        <Box
                            component="span"
                            onClick={region ? () => cycle(i) : undefined}
                            title={region
                                ? (region.kind === 'drawer'
                                    ? (shut ? 'Open this drawer (tab)' : 'Shut this drawer (tab)')
                                    : 'Cycle this heading: folded, children, all (tab)')
                                : undefined}
                            sx={{
                                flex: '0 0 auto',
                                width: '1.6ch',
                                textAlign: 'center',
                                userSelect: 'none',
                                cursor: region ? 'pointer' : 'default',
                                color: shut ? p.fg : p.gutter,
                                opacity: region ? (shut ? 0.85 : 0.55) : 0,
                            }}
                        >
                            {region ? (shut ? '▸' : '▾') : ' '}
                        </Box>
                        <Box
                            component="span"
                            sx={{
                                pl: 1.25,
                                pr: 2,
                                minWidth: 0,
                                whiteSpace: wrap ? 'pre-wrap' : 'pre',
                                overflowWrap: wrap ? 'anywhere' : 'normal',
                                flex: 1,
                            }}
                        >
                            {lineTokens(line, st, states[i].block, states[i].drawer, states[i].lang, states[i].code).map((t, j) => (
                                <span
                                    key={j}
                                    style={{
                                        color: p[t.c] || p.fg,
                                        fontWeight: t.bold ? 700 : undefined,
                                        fontStyle: t.italic ? 'italic' : undefined,
                                        textDecoration: t.strike
                                            ? 'line-through'
                                            : t.underline
                                                ? 'underline'
                                                : undefined,
                                    }}
                                >
                                    {t.s}
                                </span>
                            ))}
                            {/* What is hidden, said on the line that hides it -
                                without this a folded heading looks like a
                                heading with nothing under it. */}
                            {shut && (
                                <span style={{ color: p.gutter, opacity: 0.8 }}>
                                    {region && region.kind === 'drawer'
                                        ? ' …'
                                        : ` … ${region ? region.end - region.start : 0} lines`}
                                </span>
                            )}
                            {/* An empty line still has to take up one. */}
                            {line === '' && '​'}
                        </Box>
                    </Box>
                    );
                })}
            </Box>
            {shown < visible.length && (
                <Box sx={{ p: 1, color: p.gutter, fontSize: 12 }}>
                    … {visible.length - shown} more lines
                </Box>
            )}
        </Box>
    );
}
